def main():
 for r in RECIPES:
  r['steps_es_sha256']=hashlib.sha256(json.dumps(r['steps'],ensure_ascii=False,separators=(',',':')).encode()).hexdigest()
  r['status']='ES_FROZEN_AWAITING_PHOTOGRAPHY_AND_LOCALIZATION'
  r['total']=r['prep']+r['cook']+r['rest']
  (ROOT/'editorial'/f"{r['slug']}-20261022-es.json").write_text(json.dumps(r,ensure_ascii=False,indent=2)+'\n')
 (ROOT/'editorial'/'navidad-20261022-plan.json').write_text(json.dumps({'date':'2026-10-22','target':'https://manualdecocina.com','languages':['es','de','en','fr','it','ja','pt'],'image_contract':{'originals':8,'webp':12,'ratio':'4:3','final_step_equals_cover':True,'style':'fotografía culinaria realista, cocina casera cálida, mesa madera clara, luz natural lateral, paño lino a rayas, estantes y plantas desenfocados, sin texto/logos/marcas'},'recipes':[{'slug':r['slug'],'title':r['title'],'steps_es_sha256':r['steps_es_sha256']} for r in RECIPES]},ensure_ascii=False,indent=2)+'\n')
 print('Frozen:',len(RECIPES),'recipes;',sum(len(r['steps']) for r in RECIPES),'Spanish steps')

if __name__=='__main__': main()
